#!/usr/bin/env python3
"""The floor forge's regions table -> data/forge_regions.json (2026-10-02).

Robert: "Have it continue building floors until I say otherwise ... Make
sure there is diversity." Every floor below Lanternmere is laid out by
HomeAI's godot_forge.py from one of these regions: its rooms, its monsters,
its materials and gear, the technique hidden in it, its words. A region
that comes round again comes back deeper: "Deep", "Ancient", "Abyssal"...
-- stronger monsters, new gear, and (when Dev's model writes them) new
words. Add a region here and the forge starts using it.

Room kinds (what the forge puts in a room): entry, hall, gallery, nest,
vein, pool, cavern, garden, barracks, lore, riddle, store, den, crossing,
shrine, hidden, secret, throne.
"""
import json, os

D = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "data")


def mob(name, model, tint, scale=1.0):
    return {"name": name, "model": model, "tint": tint, "scale": scale}


